# Script de restauracao automatica do src/App.tsx
import zlib, base64, os

b64_data = """"""

content = zlib.decompress(base64.b64decode(b64_data.encode('ascii'))).decode('utf-8')
os.makedirs('src', exist_ok=True)
with open('src/App.tsx', 'w', encoding='utf-8') as f:
    f.write(content)

print('src/App.tsx restaurado com sucesso!')
